select energy_manager.load_cards($cards$[
{"id":"p2-b03-038","paper":2,"topic":"Steam System","kind":"problem","front":"Condensate on a trap at 4 bar (g) is released to atmosphere (0 bar g). Using the flash steam chart (Figure 3.28), what percentage flashes to steam?","back":"About 10%, or 0.10 kg of flash steam per kg of condensate.","explain":"The chart plots flash steam pressure against trap pressure and gives kg of flash steam per kg of condensate. The chapter's example reads 10% for this case.","flash":false,"source":"BEE Book 2 Ch 03 p126","steps":[{"prompt":"Find the pressure on the trap.","answer":"4 bar (g)","explain":"This is the upstream pressure of the condensate."},{"prompt":"Find the flash steam pressure.","answer":"0 bar (g), atmospheric pressure","explain":"The condensate is released to atmosphere."},{"prompt":"Read the chart where these two pressures meet.","answer":"10% flash steam","explain":"Read the kg flash steam per kg condensate axis at the crossing point."},{"prompt":"Apply the result.","answer":"100 kg/h of condensate gives about 10 kg/h of flash steam","explain":"Multiply the condensate flow by the fraction read from the chart."}],"order":2210},
{"id":"p2-b03-039","paper":2,"topic":"Steam System","kind":"fact","front":"What share of total pipe length can be redundant, and what should be done with it?","back":"Up to 10–15% of total length; eliminate all redundant pipelines.","explain":"Redundant pipelines are those no longer needed. Removing them reduces steam distribution losses significantly.","flash":true,"source":"BEE Book 2 Ch 03 p128","order":2211},
{"id":"p2-b03-040","paper":2,"topic":"Steam System","kind":"problem","front":"A laundry finishes 100 kg/h of dry sheets. If the sheets reach the steam-heated iron at 48% moisture, then at 52% moisture, how much steam does the iron need in each case, and what is the increase?","back":"About 62 kg/h of steam at 48% moisture and about 67 kg/h at 52%, an increase of about 8%.","explain":"Steam use rises with the water left in the sheets, because the iron must evaporate that water. The chapter's lesson is to remove as much water as possible mechanically (hydro-extractors, presses) before heating.","flash":false,"source":"BEE Book 2 Ch 03 p129","steps":[{"prompt":"Find the water to evaporate at 48% moisture.","answer":"About 48 kg of water (as stated in the chapter)","explain":"This is the water the steam-heated iron must evaporate."},{"prompt":"Find the steam needed at 48% moisture.","answer":"62 kg of steam (as stated in the chapter)","explain":"The steam required to evaporate 48 kg of water."},{"prompt":"Find the steam needed at 52% moisture.","answer":"52 kg of water evaporated, requiring about 67 kg of steam","explain":"More water left in the sheets means more steam."},{"prompt":"Find the percentage increase.","answer":"(67 − 62) / 62 = 8%","explain":"The same finished product needs about 8% more steam."}],"order":2212},
{"id":"p2-b03-041","paper":2,"topic":"Steam System","kind":"problem","front":"A refinery heats 50 t/h of crude from 35 °C to 85 °C using saturated steam. Crude specific heat is 0.631 kcal/kg °C and the plant runs 8,000 h/year. Steam at 3 bar (latent heat 517 kcal/kg) or at 8 bar (latent heat 489 kcal/kg) costs Rs 4.50/kg either way. Which should be recommended?","back":"3 bar steam: about 3,051 kg/h and Rs 10.98 crore per year, which is cheaper than 8 bar at about 3,225 kg/h and Rs 11.61 crore per year. Recommend 3 bar.","explain":"Both pressures cost the same per kg, so the cheaper option is the one with the higher latent heat per kg, which is 3 bar steam. The saving is about Rs 63 lakh per year.","flash":false,"source":"BEE Book 2 Ch 03 p130","steps":[{"prompt":"Find the heat gained by the crude.","answer":"50,000 kg/h × 0.631 × (85 − 35) = 1,577,500 kcal/h","explain":"Sensible heat gain of the crude stream."},{"prompt":"Find the steam flow at 3 bar.","answer":"1,577,500 / 517 = 3,051 kg/h","explain":"Steam mass equals heat required divided by latent heat."},{"prompt":"Find the steam flow at 8 bar.","answer":"1,577,500 / 489 = about 3,225 kg/h","explain":"Lower latent heat means more steam is needed."},{"prompt":"Find the annual cost at each pressure.","answer":"3 bar: 3,051 × 4.50 × 8,000 = Rs 10.98 crore; 8 bar: 3,225 × 4.50 × 8,000 = Rs 11.61 crore","explain":"Annual cost at Rs 4.50/kg for 8,000 h/year."},{"prompt":"Make the recommendation.","answer":"Use 3 bar steam; it saves about Rs 63 lakh per year","explain":"The lower-cost option is recommended."}],"order":2213},
{"id":"p2-b04-001","paper":2,"topic":"Furnace Classification","kind":"fact","front":"Based on the method of generating heat, what are the two broad furnace types?","back":"Combustion type (fuel fired: oil, coal or gas) and electric type.","explain":"Combustion furnaces are further classed as oil fired, coal fired or gas fired depending on the kind of combustion. Electric furnaces are resistance type (for heating) or induction and arc type (for melting metals).","flash":false,"source":"BEE Book 2 Ch 04 p135","order":2214},
{"id":"p2-b04-002","paper":2,"topic":"Furnace Classification","kind":"fact","front":"Based on the mode of charging, what are the two furnace types?","back":"Intermittent (batch or periodical) furnace and continuous furnace.","explain":"Batch furnaces are charged and heated in cycles. Continuous furnaces move stock through the chamber without stopping. The book also classes furnaces as recuperative or regenerative by the mode of waste heat recovery.","flash":false,"source":"BEE Book 2 Ch 04 p135","order":2215},
{"id":"p2-b04-003","paper":2,"topic":"Furnace Design Basics","kind":"fact","front":"Why do furnace exhaust gases leave at a very high temperature?","back":"Gases can give heat to the charge only while they are hotter than the charge, so the flue gas must leave hot.","explain":"A furnace heating stock to 1200 °C will have its exhaust gases leaving at least at 1200 °C, which causes a large stack loss. This is why furnace efficiency is far lower than boiler efficiency. Preheating the stock and the combustion air are the main ways to recover part of this heat.","flash":true,"source":"BEE Book 2 Ch 04 p136","order":2216},
{"id":"p2-b04-004","paper":2,"topic":"Typical Furnace Systems","kind":"fact","front":"What is the typical operating temperature of a forging furnace, and how is most of its heat transferred?","back":"About 1200 to 1250 °C; most heat is transmitted by radiation (open fireplace system).","explain":"Forging furnaces preheat billets and blooms to a forge temperature. Large pieces are soaked for 4 to 6 hours so the temperature is uniform through the cross-section. Manual charging and discharging causes significant heat loss.","flash":true,"source":"BEE Book 2 Ch 04 p136","order":2217},
{"id":"p2-b04-005","paper":2,"topic":"Typical Furnace Systems","kind":"fact","front":"What is the average output of a batch type rerolling mill furnace?","back":"About 10 to 15 tonnes per day, with billets or scrap of 2 to 20 kg heated to about 1200 °C.","explain":"Batch rerolling furnaces are charged and discharged manually. Their cycle has a heat-up stage and a rerolling stage. The final product is rods, strips and similar sections.","flash":false,"source":"BEE Book 2 Ch 04 p137","order":2218},
{"id":"p2-b04-006","paper":2,"topic":"Typical Furnace Systems","kind":"fact","front":"What is the typical output and operating temperature of a continuous pusher type furnace?","back":"About 50 to 100 tonnes per day at about 1250 °C, running 8 to 10 hours per day.","explain":"The stock recovers part of the heat in the flue gases as it moves down the furnace. Heat absorption is slow, steady and uniform across the section, which is an advantage over the batch type.","flash":false,"source":"BEE Book 2 Ch 04 p137","order":2219},
{"id":"p2-b04-007","paper":2,"topic":"Heat Transfer in Furnaces","kind":"fact","front":"What is the dominant mode of heat transfer in a steel reheating furnace at high temperature?","back":"Radiation from the furnace walls (wall radiation); gas radiation depends on CO₂ and water vapour, temperature and furnace geometry.","explain":"At reheating temperatures of 900 to 1250 °C, radiation dominates over convection. Gas radiation is set by the gas composition, mainly the CO₂ and water vapour concentrations, along with the temperature and geometry of the furnace.","flash":false,"source":"BEE Book 2 Ch 04 p139","order":2220},
{"id":"p2-b04-008","paper":2,"topic":"Continuous Reheating Furnaces","kind":"fact","front":"List the main disadvantages of the pusher type reheating furnace.","back":"Refractory hearth damage and skid marks; water-cooling losses from skids; discharge must accompany charge; stock size and length limited by friction and pile-ups; no all-round heating.","explain":"Pusher furnaces have low installation and maintenance cost, which is why they are popular in steel plants. Water cooled skids remove heat from the stock and furnace, which hurts energy use in top and bottom fired designs.","flash":false,"source":"BEE Book 2 Ch 04 p140","order":2221},
{"id":"p2-b04-009","paper":2,"topic":"Continuous Reheating Furnaces","kind":"fact","front":"What is the main disadvantage of a walking hearth furnace?","back":"The bottom face of the stock cannot be heated.","explain":"Small gaps between stock pieces limit side heating and raise the risk of temperature differences at discharge. Large spaces between pieces help, but the stock residence time may then be several hours.","flash":true,"source":"BEE Book 2 Ch 04 p140","order":2222},
{"id":"p2-b04-010","paper":2,"topic":"Cupola Furnace","kind":"fact","front":"What is the most commonly used iron-to-coke ratio in a cupola furnace?","back":"8:1.","explain":"The cupola is charged with alternate layers of coke, flux and iron. The flux weight is about one-fifth of the coke charge weight. Limestone is the commonly used flux.","flash":false,"source":"BEE Book 2 Ch 04 p143","order":2223},
{"id":"p2-b04-011","paper":2,"topic":"Cupola Furnace","kind":"fact","front":"Which flux is commonly used in a cupola, and what is the flux weight compared with the coke charge?","back":"Limestone (CaCO₃) is the common flux; flux weight is about 1/5th of the coke charge weight.","explain":"The flux melts and reacts with impurities in the molten metal to form slag. The slag floats on the metal and stops it oxidising. Fluorspar, sodium carbonate and calcium carbide are other fluxes the book lists.","flash":false,"source":"BEE Book 2 Ch 04 p143","order":2224},
{"id":"p2-b04-012","paper":2,"topic":"Cupola Furnace","kind":"fact","front":"What happens in the reducing zone of a cupola, and about what temperature does it reach?","back":"Hot CO₂ rising through hot coke is reduced to CO (CO₂ + C → 2CO); the zone reaches about 1200 °C.","explain":"The reducing atmosphere protects the charge from oxidation. The melting iron also picks up carbon as it trickles through this zone. Heat is absorbed by the endothermic reaction, which lowers the temperature.","flash":false,"source":"BEE Book 2 Ch 04 p144","order":2225},
{"id":"p2-b04-013","paper":2,"topic":"Cupola Furnace","kind":"fact","front":"What is a hot blast cupola and how hot can the blast air be preheated?","back":"A cupola that recovers exhaust heat to preheat blast air, up to about 400 °C, from exhaust gas near 800 °C.","explain":"Preheated blast air adds sensible heat to the furnace input and raises the combustion temperature. Blast air at 300 °C or higher gives this effect. Burning the CO in the exhaust gas adds more recoverable heat.","flash":false,"source":"BEE Book 2 Ch 04 p144","order":2226},
{"id":"p2-b04-014","paper":2,"topic":"Induction Furnaces","kind":"problem","front":"Estimate the heat (kWh) needed to melt 1 tonne of copper from 30 °C to 1130 °C, given specific heat 0.386 kJ/kg °C and latent heat 212 kJ/kg.","back":"About 177 kWh (sensible about 118 kWh plus latent about 59 kWh).","explain":"The book uses E (kWh) = m × (Cp × ΔT + latent heat) ÷ 3600, since 3600 kJ = 1 kWh. The table in the chapter shows the sensible and latent parts separately. This is the theoretical heat, not the actual electricity drawn.","steps":[{"prompt":"Find the sensible heat to raise 1000 kg of copper from 30 °C to 1130 °C.","answer":"1000 × 0.386 × (1130 − 30) = 424,600 kJ","explain":"Sensible heat is mass × specific heat × temperature rise."},{"prompt":"Find the latent heat of melting for 1000 kg of copper.","answer":"1000 × 212 = 212,000 kJ","explain":"Latent heat is the energy to change solid to liquid at the melting point, with no temperature change."},{"prompt":"Add the two heats and convert kJ to kWh.","answer":"(424,600 + 212,000) ÷ 3600 ≈ 176.8 kWh, about 177 kWh","explain":"The conversion uses 3600 kJ = 1 kWh."}],"flash":false,"source":"BEE Book 2 Ch 04 p145","order":2227},
{"id":"p2-b04-015","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"Calculate the furnace efficiency (%) for melting 1000 kg of mild steel scrap in an induction furnace. Data: specific heat 0.682 kJ/kg °C, latent heat 272 kJ/kg, melting temperature 1650 °C, charge temperature 30 °C, slag 25 kg, electricity consumed 625 kWh.","back":"About 63%: theoretical heat 394 kWh against 625 kWh actual.","explain":"The book defines efficiency as theoretical heat required ÷ actual electricity consumed × 100. The difference between actual and theoretical is the loss from conduction, radiation and other losses. Slag heat is included in the theoretical total.","steps":[{"prompt":"Find the heat to melt the metal: H₁ = W × (Cp × (T_melt − T_charge) + L) ÷ 3600.","answer":"1000 × (0.682 × 1620 + 272) ÷ 3600 = 382.45 kWh","explain":"The sensible term uses the temperature rise 1650 − 30 = 1620 °C; the latent term is added as is."},{"prompt":"Find the heat to melt the slag: H₂ = 1.65 × W_slag ÷ 3.6.","answer":"1.65 × 25 ÷ 3.6 = 11.45 kWh","explain":"The 1.65 factor and 3.6 MJ = 1 kWh are the book's constants for slag."},{"prompt":"Add the two to get the total theoretical heat.","answer":"382.45 + 11.45 = 394 kWh","explain":"Total theoretical heat is the sum of metal and slag heat."},{"prompt":"Divide by the measured electricity and multiply by 100.","answer":"394 ÷ 625 × 100 = 63%","explain":"Actual electricity is measured at the input busbar to the furnace."}],"flash":false,"source":"BEE Book 2 Ch 04 p146","order":2228},
{"id":"p2-b04-016","paper":2,"topic":"Induction Furnaces","kind":"fact","front":"What is the theoretical energy needed to melt one tonne of steel in an induction furnace, and what is the typical actual figure?","back":"Theoretical 385 to 400 kWh per tonne; actual specific energy consumption 550 to 950 kWh per tonne.","explain":"The gap between theory and practice comes from the losses in the generator, capacitor bank, crucible and radiation. Poor maintenance, low supply voltage and wrong lining also raise the figure.","flash":true,"source":"BEE Book 2 Ch 04 p147","order":2229},
{"id":"p2-b04-017","paper":2,"topic":"Induction Furnaces","kind":"fact","front":"Which part of an induction furnace has the largest loss, and about what percentage is it?","back":"The crucible (water-cooled cables, bus bar and changeover switches): 18 to 25%.","explain":"The other typical losses are the generator or panel (2 to 4%), the capacitor bank (1 to 3%) and radiation (7 to 9%). Reducing the crucible-side losses therefore gives the biggest saving.","flash":false,"source":"BEE Book 2 Ch 04 p147","order":2230},
{"id":"p2-b04-018","paper":2,"topic":"Furnace Efficiency","kind":"fact","front":"List the main reasons furnace efficiency is low.","back":"High stack temperature and excess air; low capacity utilisation or hearth loading; radiation losses through openings; surface heat losses; batch heating, cooling and soaking cycles.","explain":"Furnaces run at high temperatures, so each loss is larger than in a boiler. The book notes that good design, loading, waste heat recovery and O&M practice can take furnace efficiency to 60% and above.","flash":false,"source":"BEE Book 2 Ch 04 p148","order":2231},
{"id":"p2-b04-019","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"A rerolling mill furnace takes 10 t/hr of stock from 40 °C to 1200 °C (Cp 0.12 kcal/kg °C) and burns 600 litres/hr of oil (SG 0.92, GCV 10,000 kcal/kg). Find the furnace efficiency by the direct method.","back":"About 25.2%.","explain":"The direct method compares heat delivered to the stock with the heat in the fuel. The flue gas temperature of 650 °C does not enter the direct-method calculation; it matters only in the indirect method.","steps":[{"prompt":"Find the heat input per hour: oil flow × SG × GCV.","answer":"600 × 0.92 × 10,000 = 55,20,000 kcal/hr","explain":"Oil in litres is converted to mass with its specific gravity before multiplying by the calorific value."},{"prompt":"Find the heat delivered to the stock per hour: W × Cp × (t_final − t_initial).","answer":"10,000 × 0.12 × (1200 − 40) = 13,92,000 kcal/hr","explain":"The input weight is 10 t/hr = 10,000 kg/hr. Only the stock heat counts as useful output."},{"prompt":"Divide output by input and multiply by 100.","answer":"13,92,000 ÷ 55,20,000 × 100 = 25.2%","explain":"This is the direct-method thermal efficiency of the furnace."}],"flash":false,"source":"BEE Book 2 Ch 04 p151","order":2232},
{"id":"p2-b04-020","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"Using the same rerolling mill furnace (10 t/hr input, 92% yield, 600 litres/hr oil), find the specific fuel consumption on a finished product basis in litres per tonne.","back":"About 65.2 litres per tonne of finished product.","explain":"Specific fuel consumption is measured against saleable product, not gross input. The 92% yield accounts for scale and other losses in rolling.","steps":[{"prompt":"Find the finished product output: input × yield.","answer":"10 × 0.92 = 9.2 t/hr","explain":"Yield converts the gross input weight into the weight of finished product."},{"prompt":"Divide the fuel consumption by the finished output.","answer":"600 litres/hr ÷ 9.2 t/hr = 65.2 litres/t","explain":"Specific fuel consumption is litres of fuel per tonne of finished product."},{"prompt":"State what the result means for comparing furnaces.","answer":"65.2 litres of oil are used per tonne of finished product, so a lower figure means a better furnace.","explain":"Comparing litres per tonne of finished product allows different furnaces and yields to be compared on the same basis."}],"flash":false,"source":"BEE Book 2 Ch 04 p151","order":2233},
{"id":"p2-b04-021","paper":2,"topic":"Furnace Efficiency","kind":"fact","front":"What are the typical thermal efficiencies of pusher or rotary high-temperature furnaces, and of batch forge furnaces?","back":"Pusher or rotary: 7 to 15%; batch forge: 5 to 10%.","explain":"Low-temperature batch furnaces (540 to 980 °C) reach 20 to 30%. Indirect fired ovens below 370 °C reach 35 to 40%. These are typical ranges for planning, not design targets.","flash":false,"source":"BEE Book 2 Ch 04 p152","order":2234},
{"id":"p2-b04-022","paper":2,"topic":"Excess Air and Combustion","kind":"fact","front":"What is the air ratio, and what does it measure?","back":"Air ratio = actual air amount ÷ theoretical combustion air amount; it shows the extent of excess air.","explain":"Optimising combustion air is the most attractive and economical energy conservation measure in a furnace. Its impact grows at higher furnace temperatures. Too little air leaves unburnt components in the flue gas.","flash":true,"source":"BEE Book 2 Ch 04 p154","order":2235},
{"id":"p2-b04-023","paper":2,"topic":"Heat Distribution in Furnaces","kind":"fact","front":"Why must a burner flame not touch the stock or the refractory?","back":"Impingement de-atomises the fuel, causes black smoke and incomplete combustion, and increases scale losses on the stock.","explain":"Flames of different burners should stay clear of each other, so burners are staggered on opposite sides. The flame should also not hit the roof, and in small furnaces the burner axis is set at an upward angle.","flash":false,"source":"BEE Book 2 Ch 04 p154","order":2236},
{"id":"p2-b04-024","paper":2,"topic":"Heat Distribution in Furnaces","kind":"fact","front":"Do many small burners or a few large burners give better heat distribution in a furnace?","back":"Many smaller burners give better heat distribution and also increase furnace life.","explain":"Large burners produce a long flame that is hard to contain within the furnace walls. For small furnaces, a long golden yellow flame suits uniform heating with furnace oil, but it must not go into the chimney or out through doors.","flash":false,"source":"BEE Book 2 Ch 04 p155","order":2237},
{"id":"p2-b04-025","paper":2,"topic":"Operating Temperature","kind":"fact","front":"What is the optimum operating temperature of a slab reheating furnace and of a bogie annealing furnace?","back":"Slab reheating: 1200 °C; bogie type annealing: 650 to 750 °C.","explain":"Operating above the optimum temperature increases heat loss, excessive oxidation, decarburisation and refractory stress. The book recommends on/off controls to avoid relying on operator judgment.","flash":false,"source":"BEE Book 2 Ch 04 p155","order":2238},
{"id":"p2-b04-026","paper":2,"topic":"Operating Temperature","kind":"fact","front":"Why should operators not rely on judgment for furnace temperature control, and what is recommended instead?","back":"Judgment leads to human error and overheating; on/off temperature controls should be provided.","explain":"Operating too hot wastes fuel and damages the product and refractory. Automatic controls keep the furnace at the set point instead of relying on the operator.","flash":false,"source":"BEE Book 2 Ch 04 p156","order":2239},
{"id":"p2-b04-027","paper":2,"topic":"Waste Heat Recovery in Furnaces","kind":"fact","front":"What share of the heat input to a furnace leaves in the chimney as sensible heat in flue gases?","back":"35 to 55 per cent.","explain":"The higher the excess air and the flue gas temperature, the more heat is available for recovery. The book says waste heat recovery comes after all other energy conservation measures; minimising waste heat generation is the first priority.","flash":true,"source":"BEE Book 2 Ch 04 p158","order":2240},
{"id":"p2-b04-028","paper":2,"topic":"Waste Heat Recovery in Furnaces","kind":"fact","front":"With a furnace exhaust gas at 1000 °C, how hot can a modern recuperator preheat the combustion air, and what saving does this give?","back":"Over 500 °C, giving energy savings of up to 30% compared with cold air.","explain":"Combustion air preheating is now used in compact boilers and compact furnaces as well as large ones. Self-recuperative burners are an alternative where there is no room for an external recuperator.","flash":false,"source":"BEE Book 2 Ch 04 p159","order":2241},
{"id":"p2-b04-029","paper":2,"topic":"Waste Heat Recovery in Furnaces","kind":"fact","front":"At what exhaust gas temperatures are radiation recuperators and convection recuperators suitable?","back":"Radiation recuperators: not below about 800 °C. Convection recuperators: best below about 900 °C.","explain":"Radiation recuperators are concentric cylinders with simple construction, suited to dirty gases. Convection recuperators are tube bundles with fins, and they are better for lower exhaust temperatures.","flash":false,"source":"BEE Book 2 Ch 04 p159","order":2242},
{"id":"p2-b04-030","paper":2,"topic":"Waste Heat Recovery in Furnaces","kind":"fact","front":"In the book's example, what fuel conservation rate comes from preheating heavy oil combustion air to 400 °C with an exhaust gas inlet of 800 °C?","back":"About 20 percent.","explain":"The fuel conservation rates for oil and natural gas are plotted against preheated air and exhaust temperature. When installing a recuperator, choose the preheat temperature that balances fuel saving against equipment cost.","flash":false,"source":"BEE Book 2 Ch 04 p162","order":2243},
{"id":"p2-b04-031","paper":2,"topic":"Wall Losses and Ceramic Coatings","kind":"fact","front":"About what share of furnace fuel input goes to make up for heat losses?","back":"About 30 to 40 per cent in intermittent or continuous furnaces.","explain":"Wall loss depends on the emissivity of the wall, the conductivity of the refractories, the wall thickness and whether the furnace runs continuously or intermittently. Insulating bricks and ceramic fibre reduce the stored heat that is lost in idle periods.","flash":false,"source":"BEE Book 2 Ch 04 p163","order":2244},
{"id":"p2-b04-032","paper":2,"topic":"Wall Losses and Ceramic Coatings","kind":"fact","front":"What energy saving has been reported from ceramic coatings in furnaces, and up to what temperature does the coating last?","back":"Savings of 8 to 20%, depending on furnace type and operating conditions; long life up to 1350 °C.","explain":"Ceramic coatings are high-emissivity, water-based, non-toxic and non-flammable. They are sprayed on and air dried in under five minutes. Their emissivity increases with temperature, the opposite of conventional refractories.","flash":false,"source":"BEE Book 2 Ch 04 p164","order":2245},
{"id":"p2-b04-033","paper":2,"topic":"Wall Losses and Ceramic Coatings","kind":"problem","front":"A reheating furnace ceiling has 20 m² of surface at 80 °C, ambient 30 °C and emissivity 0.75. Find the heat release per hour from the ceiling. Use the ceiling factor a = 2.8 with Q = a × (t_s − t_a)^(5/4) + 4.88 × E × [((t_s + 273) ÷ 100)^4 − ((t_a + 273) ÷ 100)^4] kcal/hr/m².","back":"About 632 kcal/hr/m², so about 12,640 kcal/hr for 20 m².","explain":"The first term is natural convection; the second is radiation. Radiation is the larger share here because the surface is hot. Surface temperature should be averaged over many measuring points, since too few points give a large error.","steps":[{"prompt":"Find the convection term: 2.8 × (80 − 30)^(5/4).","answer":"2.8 × 132.97 ≈ 372 kcal/hr/m²","explain":"The 5/4 power is the natural convection law the book uses for the ceiling factor."},{"prompt":"Find the radiation term: 4.88 × 0.75 × [(353 ÷ 100)^4 − (303 ÷ 100)^4].","answer":"3.66 × (155.2 − 84.2) ≈ 260 kcal/hr/m²","explain":"Temperatures must be converted to absolute scale by adding 273 before the fourth power is taken."},{"prompt":"Add the two terms to get the heat release per square metre.","answer":"372 + 260 ≈ 632 kcal/hr/m²","explain":"Convection and radiation both leave the furnace skin and add together."},{"prompt":"Multiply by the ceiling area.","answer":"632 × 20 = 12,640 kcal/hr","explain":"Total loss is the per-area flux times the surface area."}],"flash":false,"source":"BEE Book 2 Ch 04 p164","order":2246},
{"id":"p2-b04-034","paper":2,"topic":"Excess Air and Combustion","kind":"problem","front":"An oil fired reheating furnace burns 440 litres/hr of oil (SG 0.92, GCV 10,200 kcal/kg, theoretical air 14 kg/kg oil). Flue gas O₂ is 14%, flue gas leaves at 300 °C, and ambient is 35 °C. Cp of flue gas is 0.23 kcal/kg °C. Find the sensible heat carried away by flue gas as a percentage of energy input.","back":"About 25.7% of energy input.","explain":"Excess air is found from the O₂ in the flue gas. The flue gas mass is the actual air plus 1 kg of fuel per kg of fuel, which is the standard approach for this calculation.","steps":[{"prompt":"Find the energy input per hour: oil mass × GCV.","answer":"440 × 0.92 = 404.8 kg/hr; 404.8 × 10,200 = 41,28,960 kcal/hr","explain":"Oil is converted from litres to kg with its specific gravity first."},{"prompt":"Find the excess air from O₂: O₂ ÷ (21 − O₂) × 100.","answer":"14 ÷ (21 − 14) × 100 = 200%","explain":"This is the standard excess air formula from flue gas O₂."},{"prompt":"Find the actual air and flue gas mass per kg oil.","answer":"Actual air = 14 × (1 + 2) = 42 kg/kg oil; flue gas = 42 + 1 = 43 kg/kg oil","explain":"Flue gas mass is the air plus the fuel that burns in it."},{"prompt":"Find the sensible heat loss per kg oil: m × Cp × (t_flue − t_ambient).","answer":"43 × 0.23 × (300 − 35) = 2620.85 kcal/kg oil","explain":"Only the temperature above ambient counts as sensible heat loss."},{"prompt":"Find the hourly loss and its share of energy input.","answer":"2620.85 × 404.8 = 10,60,920 kcal/hr; 10,60,920 ÷ 41,28,960 × 100 = 25.7%","explain":"This is the stack loss the furnace could recover with a recuperator."}],"flash":false,"source":"BEE Book 2 Ch 04 p166","order":2247}
]$cards$::jsonb);
